import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"常用组件","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/components.md","filePath":"frontend/components.md","lastUpdated":1794176980000}`),a={name:`frontend/components.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="常用组件" tabindex="-1">常用组件 <a class="header-anchor" href="#常用组件" aria-label="Permalink to “常用组件”">​</a></h1><p>本页列出前端常用的组件及其用途，适用于前端开发者。</p><p>组件统一来自 XiHan.UI（<code>@xihan-ui/vue</code> 等）。它是解剖式组件库：模板里的 <code>Xh*</code> 部件（如 <code>XhButton</code>、<code>XhDialogRoot</code>）由 Vite 插件 <code>XiHanUIResolver</code> 按需解析到具名导出，可以不写 import，摇树不受影响。组件 API、部件与令牌见 <a href="https://ui.docs.xihanfun.com" target="_blank" rel="noreferrer">XiHan.UI 文档</a>。</p><p><code>packages/components</code>（<code>~/components</code>）是应用侧的薄封装：在 XiHan.UI 之上统一表单控件的尺寸、状态与文案，并提供列表引擎 SchemaPage。不引入其他组件库，也不复制第三方组件运行时；组件库的缺陷回 XiHan.UI 修。</p><h2 id="列表与页面" tabindex="-1">列表与页面 <a class="header-anchor" href="#列表与页面" aria-label="Permalink to “列表与页面”">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>用途</th></tr></thead><tbody><tr><td><code>SchemaPage</code></td><td>Schema 驱动的列表页引擎，见 <a href="./schema-page">Schema 驱动页面</a></td></tr><tr><td><code>XDataTable</code></td><td>不走 Schema 的次级表格（抽屉、弹窗、面板里）：缺省 <code>md</code> 尺寸 + 列分隔线，传 <code>pagination</code> 出与列表页同款的分页底栏；<code>rowKey</code> 缺省 <code>basicId</code>，契约行用 <code>id</code> 时要显式传</td></tr><tr><td><code>XPageShell</code></td><td>整屏页面外壳：头部吸顶、内容区内部滚动</td></tr><tr><td><code>XEditModal</code></td><td>新增 / 编辑弹窗：给 <code>form-id</code> 后保存钮成为表单的提交钮，校验通过才走表单的 <code>@submit</code>；打开时焦点落到第一个控件</td></tr><tr><td><code>XFieldLabel</code></td><td>字段名，可带 <code>help</code>：弹出层里针对单个字段的说明收进字段名后面的问号提示</td></tr><tr><td><code>XHelpTip</code></td><td>问号提示本体（偏好设置各项、<code>XFieldLabel</code> 都用它）</td></tr><tr><td><code>renderTag(label, tone)</code></td><td>状态列等的标签渲染</td></tr></tbody></table><p>字段级错误不由弹窗自动处理：页面把 <code>ApiError.errors</code> 存起来，用 <code>XhFieldRoot :invalid</code> + <code>XhFieldErrorText</code> 显示在对应字段下。</p><h2 id="表单控件" tabindex="-1">表单控件 <a class="header-anchor" href="#表单控件" aria-label="Permalink to “表单控件”">​</a></h2><p><code>XInput</code>、<code>XNumberInput</code>、<code>XSelect</code>、<code>XCombobox</code>、<code>XCascader</code>、<code>XTreeSelect</code>、<code>XDatePicker</code>、<code>XDateRangePicker</code>、<code>XTagsInput</code>、<code>XSlider</code>、<code>XSegmented</code>、<code>XColorPicker</code>：统一尺寸、校验状态与占位文案。日期控件收发浏览器本地时区的时间戳（毫秒）。</p><h2 id="授权与选择" tabindex="-1">授权与选择 <a class="header-anchor" href="#授权与选择" aria-label="Permalink to “授权与选择”">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>用途</th></tr></thead><tbody><tr><td><code>XPermissionTransfer</code> / <code>XGrantTransfer</code></td><td>权限分配穿梭框（角色、用户直授、套餐）：条目来自权限目录 <code>permissions.list</code>，按 <code>groupPermissions</code> 分组</td></tr><tr><td><code>XTree</code></td><td>树（数据范围里的部门、缓存键、生成代码的文件）</td></tr><tr><td><code>XUserAvatar</code></td><td>用户头像：值是文件 ID 时换签名地址，没有头像时显示首字母</td></tr><tr><td><code>XFileRefUpload</code></td><td>业务表单里的文件引用上传：上传到文件库，字段只存文件 ID</td></tr></tbody></table><h2 id="其他组件" tabindex="-1">其他组件 <a class="header-anchor" href="#其他组件" aria-label="Permalink to “其他组件”">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>用途</th></tr></thead><tbody><tr><td><code>Icon</code>、<code>IconPicker</code></td><td>图标与图标选择器，见<a href="./icon">字体图标</a></td></tr><tr><td><code>XCodeEditor</code></td><td>代码编辑器（monaco，异步加载）：只读预览与模板编辑</td></tr><tr><td><code>XMdEditor</code> / <code>XContentEditorField</code></td><td>Markdown 编辑器（md-editor-v3，异步加载）与带摘要、字数的正文编辑字段（通知公告正文）</td></tr><tr><td><code>XJsonBlock</code></td><td>JSON 只读查看</td></tr><tr><td><code>XChartInView</code></td><td>进入视口才挂载的图表壳（工作台）</td></tr><tr><td><code>XPopconfirm</code>、<code>XTooltip</code>、<code>XDropdown</code>、<code>XIconButton</code></td><td>交互小件</td></tr></tbody></table><p>公共组件里没有富文本编辑器与 JSON 编辑器：正文用 Markdown 编辑器，代码与模板用 <code>XCodeEditor</code>。</p><p>以下组件不从 <code>~/components</code> 导出，按文件路径引用（<code>~/components/common/&lt;文件&gt;.vue</code>）：</p><table tabindex="0"><thead><tr><th>组件</th><th>用途</th></tr></thead><tbody><tr><td><code>CronExpression</code></td><td>Cron 构建器（作业的新建与改计划），配合 <code>jobs.validate-schedule</code> 预览执行时间</td></tr><tr><td><code>LocaleSwitcher</code>、<code>TimezoneSwitcher</code></td><td>区域与时区切换（顶栏、悬浮工具栏、偏好设置）</td></tr><tr><td><code>LockScreen</code>、<code>DynamicIsland</code>、<code>AppWatermark</code></td><td>锁屏、灵动岛、水印，挂在 <code>App.vue</code></td></tr><tr><td><code>SyncStatusBadge</code>、<code>PageLoader</code></td><td>设置同步状态、页面加载占位</td></tr></tbody></table><h2 id="写法约定" tabindex="-1">写法约定 <a class="header-anchor" href="#写法约定" aria-label="Permalink to “写法约定”">​</a></h2><ul><li>应用自有组件显式 import（<code>import { XEditModal } from &#39;~/components&#39;</code>），只有 XiHan.UI 的 <code>Xh*</code> 可由插件自动解析；</li><li>模板里 <code>xh-</code> 开头的小写标签是设计器的 Web Components（<code>vite.config.ts</code> 的 <code>isCustomElement</code>），组件库部件一律写 PascalCase；</li><li>弹窗、抽屉、浮层只用 frosted；玻璃拟态只给命令面板、登录与注册页的卡片和右上角工具条、灵动岛、标签总览遮罩、控制中心面板、页面切换的加载遮罩，统一用 <code>packages/design/ui.css</code> 的 <code>.app-glass</code> / <code>--app-glass-*</code>；</li><li>颜色、间距、圆角只用令牌，不写裸 px。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./schema-page">Schema 驱动页面</a> · <a href="./theme">布局与主题</a> · <a href="./icon">字体图标</a></li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};